  ('POLICY_PUBLISHED', 'in_app', 'en', 'Policy to acknowledge: {{name}}', 'Version {{version}} is published. Read it and acknowledge it under My policies.'),
  ('POLICY_PUBLISHED', 'email', 'en', 'Policy to acknowledge: {{name}}',
