  ('CORRECTIVE_ACTION_ASSIGNED', 'in_app', 'en', 'Corrective action for {{supplier}}', '"{{title}}" is yours, due {{due}}.'),
  ('CORRECTIVE_ACTION_ASSIGNED', 'email', 'en', 'Corrective action for {{supplier}}',
