  ('CORRECTIVE_ACTION_DUE', 'in_app', 'en', 'Corrective action {{when}}: {{supplier}}', '"{{title}}" {{when}}. Open Supply Chain → Corrective actions.'),
  ('CORRECTIVE_ACTION_DUE', 'email', 'en', 'Corrective action {{when}}: {{supplier}}',
