  ('ANOMALY_DETECTED', 'in_app', 'en', 'Unusual value: {{metric}} at {{site}}', '{{detail}} ({{period}}). Open Analytics → Anomalies to explain it.'),
  ('ANOMALY_DETECTED', 'email', 'en', 'Unusual value: {{metric}} at {{site}}',
